// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/space-grotesk";
import "@fontsource/noto-sans-kr";

export const spaceGrotesk = { variable: "" };
export const notoSansKR = { variable: "" };

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class (the name styles.css expects). Pre-reveal
 * states (opacity/translate) live in styles.css and are gated behind the
 * `.neon-js` root class, so all content is fully visible when JavaScript
 * never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms apart
 * — the street's cadence.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (reduced || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          el.style.transitionDelay = `${batch * 80}ms`;
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { spaceGrotesk, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

const TITLE = "HOLOGRAPH";

/**
 * HOLOGRAPH 홀로그래프 — a holographic card house. The signature is an
 * iridescent foil: a multi-stop conic-gradient spectrum on the wordmark whose
 * angle is driven by the pointer, so the rainbow sweeps as you move. Holographic
 * panels refract the same spectrum. Under reduced motion the foil holds a fixed
 * prismatic angle (a composed still).
 *
 * `.holograph-js` is added on mount so the no-JS markup is the finished page.
 */
export default function HolographPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const stageRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.classList.add("holograph-js");
    const id = requestAnimationFrame(() => root.classList.add("is-mounted"));
    window.parent?.postMessage({ type: "oneshot:ready", slug: "holograph" }, "*");
    return () => cancelAnimationFrame(id);
  }, []);

  // Drive the foil angle from the pointer so the rainbow sweeps live.
  useEffect(() => {
    const stage = stageRef.current;
    if (!stage || reduced) return;
    let raf = 0;
    let target = 200;
    let cur = target;
    const onMove = (e: PointerEvent) => {
      const r = stage.getBoundingClientRect();
      const nx = (e.clientX - r.left) / r.width; // 0..1
      target = 120 + nx * 240; // sweep 120deg..360deg
      if (!raf) raf = requestAnimationFrame(tick);
    };
    const tick = () => {
      cur += (target - cur) * 0.1;
      stage.style.setProperty("--hg-angle", `${cur.toFixed(1)}deg`);
      if (Math.abs(target - cur) > 0.4) raf = requestAnimationFrame(tick);
      else raf = 0;
    };
    window.addEventListener("pointermove", onMove, { passive: true });
    return () => {
      window.removeEventListener("pointermove", onMove);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [reduced]);

  return (
    <div ref={rootRef} className={`${spaceGrotesk.variable} ${notoSansKR.variable} holograph-root`}>
      <div className="holograph-bg" aria-hidden="true" />
      <div ref={revealRef} className="holograph-doc">
        <header ref={stageRef} className="holograph-hero">
          <p className="holograph-kicker">
            <span lang="ko">은박 카드 하우스</span> · FOIL CARD HOUSE · 2026
          </p>
          <h1 className="holograph-title" aria-label={TITLE}>
            <span className="holograph-foil" aria-hidden="true">
              {TITLE.split("").map((ch, i) => (
                <span key={i} className="holograph-glyph" style={{ "--hg-i": i } as CSSProperties}>
                  {ch}
                </span>
              ))}
            </span>
          </h1>
          <p className="holograph-title__ko" lang="ko">홀로그래프</p>
          <p className="holograph-sub">
            <span lang="ko">각도마다 다른 색.</span> A different color at every angle.
          </p>
          <p className="holograph-hint" lang="ko">움직여 보세요 — 무지개가 당신을 따라갑니다.</p>
        </header>

        <main>
          <section className="holograph-grid">
            {[
              { ko: "무지개 은박", en: "Rainbow foil", n: "01" },
              { ko: "보안 홀로그램", en: "Security hologram", n: "02" },
              { ko: "각도 잉크", en: "Angle-shift ink", n: "03" },
            ].map((c, i) => (
              <article key={i} className="holograph-card" data-reveal style={{ "--hg-d": i * 90 } as CSSProperties}>
                <span className="holograph-card__n">{c.n}</span>
                <span className="holograph-card__en">{c.en}</span>
                <span className="holograph-card__ko" lang="ko">{c.ko}</span>
              </article>
            ))}
          </section>

          <section className="holograph-lead" data-reveal>
            <p className="holograph-lead__p">
              <span lang="ko">
                홀로그래피는 빛의 간섭이다. 우리는 종이 위에 무지개를 인쇄하지 않는다 —
                각도를 인쇄한다. 돌리면 색이, 기울이면 빛이, 멈추면 잔상이 남는다.
              </span>{" "}
              Holography is light's interference. We don't print a rainbow on paper —
              we print an angle. Turn it and the color shifts; tilt it and the light;
              stop and the after-image stays.
            </p>
          </section>
        </main>

        <footer className="holograph-foot">
          <span>HOLOGRAPH · 2026</span>
          <span lang="ko">홀로그래프 — 서울</span>
        </footer>
      </div>
    </div>
  );
}

.holograph-root {
  --hg-bg: #0a0612;
  --hg-deep: #05030c;
  --hg-text: #f4f0ff;
  --hg-mute: #9a86b8;
  --hg-pink: #ff5edb;
  --hg-cyan: #4be3ff;
  --hg-font-display: var(--font-space), "Space Grotesk", system-ui, sans-serif;
  --hg-font-kr: "Noto Sans KR", sans-serif;
  --hg-ease: cubic-bezier(0.16, 1, 0.3, 1);
  --hg-angle: 200deg;

  min-height: 100vh;
  margin: 0;
  background: var(--hg-bg);
  color: var(--hg-text);
  font-family: var(--hg-font-kr);
  font-weight: 300;
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

.holograph-bg {
  position: fixed;
  inset: -10%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(50% 60% at 20% 30%, rgba(255, 94, 219, 0.32), transparent 70%),
    radial-gradient(46% 54% at 80% 24%, rgba(75, 227, 255, 0.28), transparent 72%),
    radial-gradient(54% 60% at 60% 84%, rgba(150, 120, 255, 0.26), transparent 72%);
  filter: blur(50px);
  opacity: 0.9;
  animation: hg-drift 30s var(--hg-ease) infinite alternate;
}
@keyframes hg-drift {
  0% { transform: translate3d(-2%, -1%, 0) scale(1.04); }
  100% { transform: translate3d(3%, 2%, 0) scale(1.1); }
}
@media (prefers-reduced-motion: reduce) { .holograph-bg { animation: none; } }

.holograph-doc {
  position: relative;
  z-index: 1;
  max-width: 1180px;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3.5rem);
}
.holograph-root ::selection { background: var(--hg-pink); color: var(--hg-deep); }

/* ---- Hero ---- */
.holograph-hero {
  min-height: 86vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(3rem, 10vh, 7rem) 0 2rem;
}
.holograph-kicker {
  margin: 0 0 1.4rem;
  font-family: var(--hg-font-display);
  font-size: clamp(0.72rem, 1.1vw, 0.86rem);
  font-weight: 500;
  letter-spacing: 0.42em;
  text-transform: uppercase;
  color: var(--hg-pink);
}
.holograph-title {
  margin: 0;
  font-family: var(--hg-font-display);
  font-weight: 700;
  font-size: clamp(2.6rem, 11vw, 9rem);
  line-height: 0.9;
  letter-spacing: -0.03em;
}
/* The iridescent foil: a conic rainbow gradient clipped to the glyphs via
   background-clip:text, with the angle driven by --hg-angle from the pointer.
   A chromatic-aberration drop completes the foil look. */
.holograph-foil {
  display: inline-block;
  background: conic-gradient(
    from var(--hg-angle),
    #ff5edb, #ffd23d, #4be3ff, #6c5cff, #5effb0, #ff5edb
  );
  background-size: 100% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 4px 18px rgba(255, 94, 219, 0.4)) drop-shadow(0 0 1px rgba(75, 227, 255, 0.6));
}
.holograph-glyph { display: inline-block; }
.holograph-title__ko {
  margin: 0.6rem 0 0;
  font-family: var(--hg-font-kr);
  font-weight: 300;
  font-size: clamp(1rem, 2.4vw, 1.6rem);
  letter-spacing: 0.42em;
  color: var(--hg-mute);
}
.holograph-sub {
  margin: 1.6rem 0 0.4rem;
  font-size: clamp(1.05rem, 1.9vw, 1.4rem);
  font-weight: 400;
}
.holograph-sub span[lang="ko"] { color: var(--hg-mute); margin-right: 0.5rem; }
.holograph-hint {
  margin: 0;
  font-size: 0.86rem;
  color: var(--hg-cyan);
  opacity: 0.85;
}

/* ---- Grid cards (smaller holographic panels) ---- */
.holograph-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: clamp(0.9rem, 1.6vw, 1.3rem);
  padding: clamp(1rem, 3vw, 2rem) 0;
}
.holograph-card {
  position: relative;
  padding: clamp(1.2rem, 2.4vw, 1.8rem);
  border-radius: 18px;
  min-height: 160px;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  justify-content: flex-end;
  background:
    linear-gradient(135deg, rgba(255, 94, 219, 0.16), rgba(75, 227, 255, 0.14)),
    rgba(14, 8, 24, 0.5);
  border: 1px solid transparent;
  background-clip: padding-box;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.16), 0 24px 48px -28px rgba(5, 3, 12, 0.9);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  overflow: hidden;
}
.holograph-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: conic-gradient(from var(--hg-angle), #ff5edb, #ffd23d, #4be3ff, #6c5cff, #5effb0, #ff5edb);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: 0.7;
  pointer-events: none;
}
.holograph-card__n { font-family: var(--hg-font-display); font-weight: 700; font-size: 0.8rem; color: var(--hg-pink); letter-spacing: 0.2em; }
.holograph-card__en { font-family: var(--hg-font-display); font-weight: 500; font-size: 1.2rem; }
.holograph-card__ko { font-size: 0.9rem; color: var(--hg-mute); }

.holograph-lead {
  padding: clamp(2.5rem, 6vw, 4rem) 0;
  border-top: 1px solid rgba(255, 94, 219, 0.16);
}
.holograph-lead__p {
  margin: 0 auto;
  max-width: 62ch;
  font-family: var(--hg-font-display);
  font-weight: 300;
  font-size: clamp(1.15rem, 2.4vw, 1.7rem);
  line-height: 1.5;
  text-align: center;
}
.holograph-lead__p span[lang="ko"] {
  display: block;
  font-family: var(--hg-font-kr);
  color: var(--hg-mute);
  font-size: 0.74em;
  margin-bottom: 0.6em;
}

.holograph-foot {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: clamp(2rem, 5vw, 3rem) 0;
  border-top: 1px solid rgba(255, 94, 219, 0.16);
  font-size: 0.8rem;
  letter-spacing: 0.06em;
  color: var(--hg-mute);
  font-family: var(--hg-font-display);
}

/* ---- Reveal gating ---- */
.holograph-js [data-reveal] {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 800ms var(--hg-ease), transform 800ms var(--hg-ease);
  transition-delay: calc(var(--hg-d, 0) * 1ms);
}
.holograph-js [data-reveal].is-visible { opacity: 1; transform: none; }
.holograph-js .holograph-glyph {
  opacity: 0;
  transform: translateY(0.35em);
  display: inline-block;
  transition: opacity 700ms var(--hg-ease), transform 700ms var(--hg-ease);
  transition-delay: calc(var(--hg-i) * 70ms + 150ms);
}
.holograph-js.is-mounted .holograph-glyph { opacity: 1; transform: none; }

@media (prefers-reduced-motion: reduce) {
  .holograph-js [data-reveal], .holograph-js .holograph-glyph {
    opacity: 1 !important; transform: none !important; transition: none !important;
  }
}
.holograph-root :focus-visible { outline: 2px solid var(--hg-pink); outline-offset: 3px; }
